select bp.patient_id as patientId, bp.`name` as patientName, bp.medical_number as medicalNumber, bp.birthday, timestampdiff(year, bp.birthday, curdate()) as age, case when bp.gender = 0 then '男' when bp.gender = 1 then '女' else '未知' end as gender, bp.mobile, bp.vip_logo as patientType, pm.cumulative_consumption as totalConsumeAmount, pm.total_arrears as totalOweAmount, pm.member_level_name as memberTypeName, pm.member_balance as memberBalance, pm.principal_balance as principalBalance, bp.origin_id as patientOrionName, bp.origin_type_name as patientOrionTypeName, bpgr.patientGroupName, date_format(bp.first_visit_date, '%Y/%m/%d') as firstVisitDate, bo.abbreviation as firstVisitOutpatient, be.employee_name as firstVisitDoctors, date_format(bp.last_visit_date, '%Y/%m/%d') as lastVisitDate, bo2.abbreviation as lastVisitOutpatient, be1.employee_name as lastVisitDoctors, pm.number_of_visits as treatQuantity from base_patient bp left join base_employee be on be.user_id = bp.first_visit_doctors left join base_employee be1 on be1.user_id = bp.last_visit_doctors left join base_organization bo on bo.org_id = bp.first_visit_outpatient left join base_organization bo2 on bo2.org_id = bp.last_visit_outpatient left join patient_manage pm on bp.patient_id = pm.patient_id left join ( SELECT patient_id, GROUP_CONCAT(group_name) AS patientGroupName FROM base_patient_group_relation GROUP BY patient_id ) bpgr on bpgr.patient_id = bp.patient_id
and bp.medical_number is not null and substr(bp.medical_number, 1, 1) != '*'
and concat(IFNULL(bp.`name`,''), IFNULL(bp.pinyin_name,''), IFNULL(bp.mobile,''), IFNULL(bp.medical_number,'')) like concat(concat('%',#{query.patientKeyWord}),'%')
and date_format(bp.birthday, '%Y') >= #{startAge} and date_format(bp.birthday, '%Y') <= #{endAge}
and bp.vip_logo = #{query.patientType}
and pm.member_level_id = #{query.memberType}
and bp.gender = #{query.gender}
and bp.first_visit_outpatient = #{query.firstOrgId}
and bp.last_visit_outpatient in
#{item}
and date_format(bp.birthday, '%m-%d') = #{query.birthday}
and be.employee_name like concat('%', #{query.firstDentistName}, '%')
and be1.employee_name like concat('%', #{query.lastDentistName}, '%')
and pm.total_arrears >= #{query.startOweAmount} and pm.total_arrears <= #{query.endOweAmount}
and pm.principal_balance >= #{query.startPrincipalBalance} and pm.principal_balance <= #{query.endPrincipalBalance}
and pm.member_balance >= #{query.startMemberBalance} and pm.member_balance <= #{query.endMemberBalance}
and pm.cumulative_consumption >= #{query.startConsumeAmount} and pm.cumulative_consumption <= #{query.endConsumeAmount}
and pm.number_of_visits >= #{query.startTreatQuantity} and pm.number_of_visits <= #{query.endTreatQuantity}
and bp.`name` in (select `name` from base_patient where `name` is not null and trim(`name`) != "" group by `name` having count(*) > 1)
and bp.mobile in (select `mobile` from base_patient where mobile is not null and trim(mobile) != "" group by `mobile` having count(*) > 1)
and concat(bp.`name`, ',', bp.`mobile`) in ( select concat(`name`, ',', `mobile`) from base_patient where mobile is not null and trim(mobile) != "" and `name` is not null and trim(`name`) != "" group by `name`, `mobile` having count(*) > 1 )
AND EXISTS ( SELECT bpg.patient_id FROM base_patient_group_relation bpg WHERE bpg.patient_id = bp.patient_id AND bpg.group_id = #{query.patientGroupId} )
and FIND_IN_SET(#{query.patientExtId0}, bp.patient_ext0)
order by bp.`name`
order by bp.`mobile`

SELECT p.patient_id , p.name as 'patientName' , p.mobile , p.gender , TimeStampDiff(YEAR, p.birthday, now()) as 'age' , p.medical_number , lo.abbreviation , p.vip_logo , ifnull(p.visit_rate, 0) as 'visit_rate' , ifnull(p.cumulative_consumption, 0) as 'cumulative_consumption' , p.vip_score , date_format(p.last_visit_date, '%Y-%m-%d') as 'last_visit_date' , ifnull(t.appoint_start_time, '') as 'nextAppointTime' , ifnull(v.remind_time, '') as 'nextRemindTime' , m.member_level_name , c.coupon_name , p.vip_logo_old FROM base_patient p left join ( select m.patient_id, m.member_level_name, m.member_level_id from base_patient_member m where m.type = 0 and m.member_level_id < 4 ) m on p.patient_id = m.patient_id left join ( select c.patient_id, max(g.coupon_name) as 'coupon_name' from base_card c left join base_coupon g on c.coupon_id = g.coupon_id where c.status > 1 and (g.coupon_name like '%365%' or g.product_type_name in ('青藤', '银藤', '金藤')) group by c.patient_id ) c on p.patient_id = c.patient_id left join base_organization lo on p.last_visit_outpatient = lo.org_id left join ( select t.patient_id, date_format(min(t.appoint_start_time), '%Y-%m-%d') as 'appoint_start_time' from base_treatment_process t where t.appointment_id is not null and t.treatment_id is null and t.appoint_start_time >= date_add(date_format(now(), '%Y-%m-%d'), INTERVAL 1 DAY) group by t.patient_id ) t on p.patient_id = t.patient_id left join ( select v.patient_id, date_format(min(v.time), '%Y-%m-%d') as 'remind_time' from base_visit_remind v where v.type = 1 and v.time >= date_add(date_format(now(), '%Y-%m-%d'), INTERVAL 1 DAY) group by v.patient_id ) v on p.patient_id = v.patient_id
p.vip_logo is not null
and concat(ifnull(p.name, ''), ifnull(p.pinyin_name, ''), ifnull(p.mobile, '')) like concat('%', #{form.combination}, '%')
and p.last_visit_outpatient in
#{item}
and p.vip_logo in
#{item}
and p.vip_logo_old in
#{item}
and m.member_level_id in
#{item}

SELECT bp.patient_id AS patientId, bp.medical_number AS medicalNumber, bp.name AS patientName, bp.mobile, TIMESTAMPDIFF(YEAR,bp.birthday,CURDATE()) AS age, bp.gender, bpm.member_level_name AS memberLevelName, bp.origin_type_name AS originTypeName, bpo.originName, ifnull(bb.receivedAmount,0) AS receivedAmount, ifnull(bb1.cumulativeConsumption,0), ifnull(bb1.totalArrears,0), bo.abbreviation, DATE_FORMAT(bp.first_visit_date,'%Y-%m-%d') AS firstVisitDate, be.employee_name AS firstVisitDoctor, DATE_FORMAT(bp.last_visit_date,'%Y-%m-%d') AS lastVisitDate, be1.employee_name AS lastVisitDoctor FROM base_patient bp INNER JOIN( select patient_id AS patientId, sum(bb.received_amount) as receivedAmount from base_bill bb
and DATE_FORMAT(bb.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT(bb.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT(bb.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT(bb.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT(bb.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT(bb.bill_date, '%Y') <= #{query.endDate}
group by bb.patient_id ) bb ON bb.patientId=bp.patient_id LEFT JOIN ( select patient_id, sum(bb.actual_amount) as cumulativeConsumption, sum(bb.debt_amount) as totalArrears from base_bill bb group by bb.patient_id ) bb1 ON bp.patient_id = bb1.patient_id LEFT JOIN ( SELECT id AS origin_id, origin_type, name AS originName FROM base_patient_origin bpo WHERE bpo.parent_id>2 UNION ALL SELECT user_id AS origin_id, 1 AS origin_type, employee_name AS originName FROM base_employee UNION ALL SELECT patient_id AS origin_id, 2 AS origin_type, name AS originName FROM base_patient ) bpo ON bp.origin_type = bpo.origin_type AND bp.origin_id = bpo.origin_id LEFT JOIN (SELECT * FROM base_patient_member where type=0) bpm ON bpm.patient_id=bp.patient_id LEFT JOIN base_employee be ON be.user_id=bp.first_visit_doctors LEFT JOIN base_employee be1 ON be1.user_id=bp.last_visit_doctors LEFT JOIN base_organization bo ON bo.org_id=bp.first_visit_outpatient
AND bp.origin_type in
#{item}

SELECT btp.treatment_id AS treatmentId, btp.registered_dentist_id AS dentistId, bb.bill_id AS billId, btp.org_id AS orgId, bo.abbreviation, bb.order_date AS orderDate, btp.registered_dentist_id AS dentistId, be.employee_name AS dentistName, btp.patient_id AS patientId, btp.treat_type AS treatType, bp.name AS patientName, bp.medical_number AS medicalNumber, bp.mobile AS mobile, brv.return_date AS returnDate, brv.return_reason AS returnReason, brv.return_content AS returnContent, brv.register_name AS registerName FROM (select MAX(treatment_id) AS treatment_id from base_treatment_process WHERE treatment_id > 0 GROUP BY patient_id) btm LEFT JOIN base_treatment_process btp ON btp.treatment_id = btm.treatment_id LEFT JOIN ( SELECT bb.bill_id, bb.treatment_id, bb.order_date FROM base_bill bb
AND EXISTS ( SELECT bbd.bill_detail_id FROM base_bill_detail bbd WHERE bb.bill_id = bbd.bill_id AND bbd.item_type = #{query.itemType}
AND bbd.item_id IN
#{item}
)
) bb ON bb.treatment_id = btm.treatment_id LEFT JOIN base_patient bp ON bp.patient_id = btp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id LEFT JOIN base_organization bo ON btp.org_id = bo.org_id LEFT JOIN ( SELECT brv.* FROM (SELECT MAX(id) AS id FROM base_return_visit GROUP BY treatment_id) tmp LEFT JOIN base_return_visit brv ON brv.id = tmp.id ) brv ON brv.treatment_id = btp.treatment_id
bp.last_visit_doctors is not NULL
and concat(IFNULL(bp.name,''),IFNULL(bp.pinyin_name,''),IFNULL(bp.mobile,'')) like concat(concat('%',#{query.combination}),'%')
AND DATEDIFF(DATE_FORMAT(now(),'%Y-%m-%d'), DATE_FORMAT(bb.order_date,'%Y-%m-%d')) <= #{query.days}
AND DATEDIFF(DATE_FORMAT(now(),'%Y-%m-%d'), DATE_FORMAT(bb.order_date,'%Y-%m-%d')) > #{query.days}
AND btp.treat_type IN
#{item}
AND btp.registered_dentist_id IN
#{item}
AND btp.org_id IN
#{item}
ORDER BY bb.order_date DESC

