    bp.patient_id AS patientId,
    bp.name AS patientName,
    bp.mobile,
    bp.medical_number AS medicalNumber,
    bp.birthday,
    bp.last_visit_date AS lastVisitDate,
    be.employee_name AS dentistName,
    bo.abbreviation
FROM base_patient bp
INNER JOIN (
    SELECT
        btp.patient_id,
        btp.registered_dentist_id,
        btp.org_id
    FROM base_treatment_process btp


            AND btp.org_id IN

                #{item}



            AND btp.registered_dentist_id IN

                #{item}




                and DATE_FORMAT(btp.treat_start_time, '%Y-%m-%d') >= #{query.startDate}


                and DATE_FORMAT(btp.treat_start_time, '%Y-%m-%d') <= #{query.endDate}




                and DATE_FORMAT(btp.treat_start_time, '%Y-%m') >= #{query.startDate}


                and DATE_FORMAT(btp.treat_start_time, '%Y-%m') <= #{query.endDate}




                and DATE_FORMAT(btp.treat_start_time, '%Y') >= #{query.startDate}


                and DATE_FORMAT(btp.treat_start_time, '%Y') <= #{query.endDate}



    GROUP BY btp.patient_id, btp.registered_dentist_id, btp.org_id
) btp ON btp.patient_id = bp.patient_id
LEFT JOIN base_employee be ON be.user_id = btp.registered_dentist_id
LEFT JOIN base_organization bo ON bo.org_id = btp.org_id
